package bo.com.ganadero.animales.infrastructure; import bo.com.ganadero.animales.domain.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Repository; import java.util.*;
@Repository class JdbcRazaRepository implements RazaRepository {private final JdbcClient jdbc;JdbcRazaRepository(JdbcClient j){jdbc=j;}public List<Raza> findActive(UUID e){return jdbc.sql("select * from ganado.razas where activo and (empresa_id is null or empresa_id=:e) order by nombre").param("e",e).query((r,n)->new Raza(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getString("codigo"),r.getString("nombre"),r.getString("especie"),r.getString("descripcion"),r.getBoolean("activo"))).list();}public Optional<Raza> findById(UUID id,UUID e){return jdbc.sql("select * from ganado.razas where id=:id and activo and (empresa_id is null or empresa_id=:e)").param("id",id).param("e",e).query((r,n)->new Raza(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getString("codigo"),r.getString("nombre"),r.getString("especie"),r.getString("descripcion"),r.getBoolean("activo"))).optional();}}
